    readonly Dictionary<string,UserModel> userModels=new Dictionary<string,UserModel>();
    readonly Dictionary<string,string> userRoots=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);
    string UserFolder {get{return Path.Combine(Experiments,"user_assemblies");}}
    static bool UserId(string id){return Regex.IsMatch(id??"","^user_[a-f0-9]{32}$");}
    static string StableId(string prefix,string reference){using(var h=SHA256.Create())return prefix+BitConverter.ToString(h.ComputeHash(System.Text.Encoding.UTF8.GetBytes(reference))).Replace("-","").ToLowerInvariant().Substring(0,24);}
    void SaveUserModel(UserModel m){AtomicJson(Path.Combine(m.Directory,"model.json"),m);userModels[m.Id]=m;userRoots[m.Path]=Path.Combine(m.Directory,"files");}
    UserModel GetUserModel(string id){if(!UserId(id))throw new Exception("INVALID_MODEL_ID");UserModel m;if(userModels.TryGetValue(id,out m))return m;string dir=Path.Combine(UserFolder,id.Substring(5)),file=Path.Combine(dir,"model.json");OwnedPath(file,"user_assemblies");if(!File.Exists(file))throw new Exception("MODEL_NOT_REGISTERED");m=Json.Deserialize<UserModel>(File.ReadAllText(file));if(m.Id!=id||m.Directory!=dir||!m.Files.Contains(m.Path))throw new Exception("MODEL_MANIFEST_INVALID");foreach(string p in m.Files){OwnedPath(p,"user_assemblies");if(!p.StartsWith(Path.Combine(dir,"files")+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new Exception("MODEL_MANIFEST_INVALID");}SaveUserModel(m);return m;}
    public object UserEnvironment(){return new{version="0.4.0-alpha.1",solidworks_revision=Sw.RevisionNumber(),solidworks_process_id=Sw.GetProcessID(),user_control=Sw.UserControl,motion_profile="rigid_assemblies_with_existing_mates",calibrated_motor_revision="34.0.0",current_motor_adapter_available=Sw.RevisionNumber()=="34.0.0",maximum_duration_s=30,maximum_frames=1801,maximum_pose_samples=100000,maximum_components=500,default_solver="Motion Analysis",source_files_written=false,curve_source="solver_component_origin_poses_and_numeric_derivatives",unsupported=new[]{"automatic_mate_inference","virtual_parts","SpeedPak","unresolved_components","unvalidated_flexible_subassemblies","force_or_contact_accuracy_certification"}};}
    public object UserListModels(){if(Directory.Exists(UserFolder))foreach(string d in System.IO.Directory.GetDirectories(UserFolder)){string id="user_"+Path.GetFileName(d);if(UserId(id)&&File.Exists(Path.Combine(d,"model.json")))GetUserModel(id);}return userModels.Values.Select(m=>new{model_id=m.Id,path=m.Path,configuration=m.Configuration,revision=m.Revision}).ToArray();}
    void LoadUserMotion(){string executable=Sw.GetExecutablePath();string directory=Directory.Exists(executable)?executable:Path.GetDirectoryName(executable);string addon=Path.Combine(directory,"cmotionsw.dll");if(!File.Exists(addon))throw new Exception("MOTION_ADDIN_NOT_INSTALLED");int status=Sw.LoadAddIn(addon);Log("USER_LOAD_MOTION "+status+" path="+addon);if(status!=0&&status!=2)throw new Exception("MOTION_ADDIN_LOAD_FAILED "+status);}
    string[] DiskDependencies(string path,bool recurse){var raw=Sw.GetDocumentDependencies2(path,recurse,true,false) as Array;if(raw==null)return new string[0];var v=raw.Cast<object>().Select(Convert.ToString).ToArray();if(v.Length%2!=0)throw new Exception("DEPENDENCY_LIST_INVALID");return Enumerable.Range(0,v.Length/2).Select(i=>Path.GetFullPath(v[2*i+1])).Distinct(StringComparer.OrdinalIgnoreCase).ToArray();}
    public object ImportUserAssembly(string source,string configuration){
        LoadUserMotion();source=Path.GetFullPath(source);if(!source.EndsWith(".SLDASM",StringComparison.OrdinalIgnoreCase)||!File.Exists(source))throw new Exception("ASSEMBLY_FILE_REQUIRED");
        var inputs=new[]{source}.Concat(DiskDependencies(source,true)).Distinct(StringComparer.OrdinalIgnoreCase).ToArray();var documents=(Sw.GetDocuments() as object[]??new object[0]).Cast<IModelDoc2>().ToArray();
        foreach(string p in inputs){if(!File.Exists(p)||!new[]{".SLDASM",".SLDPRT"}.Contains(Path.GetExtension(p).ToUpperInvariant()))throw new Exception("SOURCE_REFERENCE_MISSING_OR_UNSUPPORTED "+p);var open=documents.FirstOrDefault(d=>d.GetPathName().Equals(p,StringComparison.OrdinalIgnoreCase));if(open!=null&&open.GetSaveFlag())throw new Exception("SOURCE_REFERENCE_HAS_UNSAVED_CHANGES "+p);}
        string uid=Guid.NewGuid().ToString("N"),dir=Path.Combine(UserFolder,uid),files=Path.Combine(dir,"files");Directory.CreateDirectory(files);var m=new UserModel{Id="user_"+uid,Directory=dir,Configuration=null,Files=inputs.Select((p,i)=>Path.Combine(files,i.ToString("D4")+"_"+uid.Substring(0,8)+"_"+Path.GetFileName(p))).ToArray()};m.Path=m.Files[0];foreach(string p in inputs)m.SourceHashes[p]=FileHash(p);
        for(int i=0;i<inputs.Length;i++){File.Copy(inputs[i],m.Files[i],false);File.SetAttributes(m.Files[i],FileAttributes.Normal);}
        // Never open the source. Resolve and rebind disk copies before SOLIDWORKS opens any imported assembly.
        for(int i=0;i<inputs.Length;i++)foreach(string reference in DiskDependencies(inputs[i],false)){int j=Array.FindIndex(inputs,p=>p.Equals(reference,StringComparison.OrdinalIgnoreCase));if(j<0||!Sw.ReplaceReferencedDocument(m.Files[i],reference,m.Files[j]))throw new Exception("COPY_REFERENCE_REDIRECT_FAILED "+reference);}
        foreach(string p in m.Files)foreach(string reference in DiskDependencies(p,true))if(!m.Files.Contains(reference,StringComparer.OrdinalIgnoreCase))throw new Exception("COPY_REFERENCE_NOT_ISOLATED "+reference);VerifyUserSources(m);SaveUserModel(m);
        AtomicJson(Path.Combine(dir,"import-evidence.json"),new{source_path=source,source_hashes=m.SourceHashes,copy_paths=m.Files,copy_method="disk_copy_then_ReplaceReferencedDocument_before_open",source_documents_opened_by_importer=false});
        using(var scope=new Scope(this,m.Path,null)){if(!string.IsNullOrEmpty(configuration)&&scope.Doc.ConfigurationManager.ActiveConfiguration.Name!=configuration&&!scope.Doc.ShowConfiguration2(configuration))throw new Exception("CONFIGURATION_NOT_FOUND");m.Configuration=scope.Doc.ConfigurationManager.ActiveConfiguration.Name;Fingerprint(scope.Doc);InspectUserCore(m,scope.Doc);Save(scope.Doc,m.Path);}
        SaveUserModel(m);VerifyUserSources(m);var checkpoint=CreateUserCheckpoint(m.Id);return new{model_id=m.Id,path=m.Path,configuration=m.Configuration,file_count=m.Files.Length,source_files_unchanged=true,checkpoint=checkpoint,preflight=PreflightUserMotion(m.Id,null)};
    }
    void VerifyUserSources(UserModel m){foreach(var p in m.SourceHashes)if(!File.Exists(p.Key)||FileHash(p.Key)!=p.Value)throw new Exception("SOURCE_FILE_CHANGED "+p.Key);}
    static IComponent2[] UserComponents(IModelDoc2 d){return ((object[])((IAssemblyDoc)d).GetComponents(false)).Cast<IComponent2>().OrderBy(c=>c.Name2,StringComparer.Ordinal).ToArray();}
    object[] InspectUserCore(UserModel m,IModelDoc2 doc){
        var result=new List<object>();foreach(var c in UserComponents(doc)){bool suppressed=c.IsSuppressed();string path=c.GetPathName();if(!suppressed&&(!File.Exists(path)||!path.StartsWith(Path.Combine(m.Directory,"files")+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)))throw new Exception("COPY_REFERENCE_NOT_ISOLATED "+c.Name2);
            string reference=Convert.ToBase64String((byte[])doc.Extension.GetPersistReference3(c)),id=StableId("component_",reference);m.Components[id]=reference;bool sub=path.EndsWith(".SLDASM",StringComparison.OrdinalIgnoreCase);var transform=c.Transform2==null?null:(double[])c.GetTotalTransform(false).ArrayData;
            result.Add(new{component_id=id,instance=c.Name2,path=path,configuration=c.ReferencedConfiguration,suppressed=suppressed,loaded=c.GetModelDoc2()!=null,fixed_component=c.IsFixed(),subassembly=sub,solving=c.Solving,speedpak=c.IsSpeedPak,transform=transform});}
        return result.ToArray();
    }
    IComponent2 ResolveUserComponent(UserModel m,IModelDoc2 doc,string id){string reference;if(!m.Components.TryGetValue(id,out reference))throw new Exception("COMPONENT_ID_NOT_FOUND");int e;var c=doc.Extension.GetObjectByPersistReference3(Convert.FromBase64String(reference),out e) as IComponent2;if(c==null||e!=0)throw new Exception("COMPONENT_REFERENCE_STALE");return c;}
    public object InspectUserModel(string id){var m=GetUserModel(id);using(var s=new Scope(this,m.Path,null)){Fingerprint(s.Doc);var components=InspectUserCore(m,s.Doc);var mates=UserMates(s.Doc);SaveUserModel(m);return new{model_id=id,configuration=s.Doc.ConfigurationManager.ActiveConfiguration.Name,components=components,mates=mates,degrees_of_freedom=new{status="unknown",reason="not inferred from mate count; native solver diagnostics and drive validation required"},source_files_unchanged=UserSourcesUnchanged(m)};}}
    bool UserSourcesUnchanged(UserModel m){return m.SourceHashes.All(p=>File.Exists(p.Key)&&FileHash(p.Key)==p.Value);}
    object[] UserMates(IModelDoc2 doc){var items=new List<object>();var feature=(IFeature)doc.FirstFeature();while(feature!=null){if(feature.GetTypeName2()=="MateGroup"){var f=(IFeature)feature.GetFirstSubFeature();while(f!=null){var mate=f.GetSpecificFeature2() as IMate2;if(mate!=null){bool warning;int error=f.GetErrorCode2(out warning);items.Add(new{name=f.Name,type=mate.Type,alignment=mate.Alignment,error=error,warning=warning,entities=Enumerable.Range(0,mate.GetMateEntityCount()).Select(i=>{var entity=mate.MateEntity(i);return new{instance=entity.ReferenceComponent==null?null:entity.ReferenceComponent.Name2,reference_type=entity.ReferenceType2};}).ToArray()});}f=(IFeature)f.GetNextSubFeature();}}feature=(IFeature)feature.GetNextFeature();}return items.ToArray();}
    public object UserStudies(string id){var m=GetUserModel(id);LoadUserMotion();using(var s=new Scope(this,m.Path,null)){Fingerprint(s.Doc);var mgr=(IMotionStudyManager)s.Doc.Extension.GetMotionStudyManager();return new{model_id=id,studies=Names(mgr).Select(n=>{var study=(IMotionStudy)mgr.GetMotionStudy(n);return new{name=n,type=study.StudyType,duration_s=study.GetDuration(),output_fps=((IMotionStudyProperties)study.GetProperties(study.StudyType)).GetFrameRate(),active=study.IsActive,motion_features=MotionFeatures(study)};}).ToArray()};}}
    object[] MotionFeatures(IMotionStudy study){var features=study.GetMotionFeatures() as object[]??new object[0];return features.Cast<IFeature>().Select(f=>{var motor=f.GetDefinition() as ISimulationMotorFeatureData;return (object)new{name=f.Name,type=f.GetTypeName2(),motor_type=motor==null?(int?)null:motor.MotorType,motion_type=motor==null?(int?)null:motor.MotionType,magnitude_raw=motor==null?(double?)null:motor.Magnitude};}).ToArray();}
    public object PreflightUserMotion(string id,string studyName){var m=GetUserModel(id);LoadUserMotion();using(var s=new Scope(this,m.Path,null)){return UserPreflight(m,s.Doc,studyName,true);}}
    object UserPreflight(UserModel m,IModelDoc2 doc,string studyName,bool resolve){
        Fingerprint(doc);if(resolve)((IAssemblyDoc)doc).ResolveAllLightWeightComponents(true);var c=UserComponents(doc);var blockers=new List<string>();var warnings=new List<string>();
        if(c.Length>500)blockers.Add("COMPONENT_BUDGET_EXCEEDED");if(c.Length==0)blockers.Add("EMPTY_ASSEMBLY");var active=c.Where(v=>!v.IsSuppressed()).ToArray();if(active.All(v=>v.IsFixed()))blockers.Add("ALL_COMPONENTS_FIXED");
        foreach(var v in active){if(v.IsSpeedPak)blockers.Add("SPEEDPAK "+v.Name2);if(v.GetModelDoc2()==null)blockers.Add("UNRESOLVED_COMPONENT "+v.Name2);if(v.GetPathName().EndsWith(".SLDASM",StringComparison.OrdinalIgnoreCase)&&v.Solving==1)blockers.Add("FLEXIBLE_SUBASSEMBLY_NOT_VALIDATED "+v.Name2);}
        bool rebuild=doc.EditRebuild3();if(!rebuild)blockers.Add("REBUILD_FAILED");var f=(IFeature)doc.FirstFeature();while(f!=null){bool w;int error=f.GetErrorCode2(out w);if(error!=0)blockers.Add("FEATURE_ERROR "+f.Name+" "+error);if(w)warnings.Add("FEATURE_WARNING "+f.Name);f=(IFeature)f.GetNextFeature();}
        foreach(var row in UserMates(doc)){var d=Json.Deserialize<Dictionary<string,object>>(Json.Serialize(row));if(Convert.ToInt32(d["error"])!=0)blockers.Add("MATE_ERROR "+d["name"]);}
        var mgr=(IMotionStudyManager)doc.Extension.GetMotionStudyManager();if(!string.IsNullOrEmpty(studyName)){var study=(IMotionStudy)mgr.GetMotionStudy(studyName);if(study==null)blockers.Add("STUDY_NOT_FOUND");else if(study.StudyType!=4)blockers.Add("MOTION_ANALYSIS_REQUIRED_EXPLICIT_CONVERSION");}
        warnings.Add("DOF_NOT_PROVEN_FROM_MATE_COUNT");if(c.Any(v=>v.IsSuppressed()))warnings.Add("SUPPRESSED_INSTANCES_EXCLUDED_FROM_ACTIVE_MOTION_SCOPE");InspectUserCore(m,doc);SaveUserModel(m);
        return new{model_id=m.Id,ready=blockers.Count==0,blockers=blockers.Distinct().ToArray(),warnings=warnings.Distinct().ToArray(),components=c.Length,active_components=active.Length,omitted_suppressed_instances=c.Where(v=>v.IsSuppressed()).Select(v=>v.Name2).ToArray(),degrees_of_freedom_status="unknown",native_rebuild_succeeded=rebuild,configuration=doc.ConfigurationManager.ActiveConfiguration.Name};
    }
    void RequireUserReady(UserModel m,IModelDoc2 doc,string study){var p=Json.Deserialize<Dictionary<string,object>>(Json.Serialize(UserPreflight(m,doc,study,true)));if(!(bool)p["ready"])throw new Exception("MODEL_PREFLIGHT_FAILED "+Json.Serialize(p["blockers"]));}
    public object UserDriveCandidates(string id){var m=GetUserModel(id);using(var s=new Scope(this,m.Path,null)){Fingerprint(s.Doc);var components=InspectUserCore(m,s.Doc);var entities=new List<object>();foreach(var c in UserComponents(s.Doc).Where(c=>!c.IsSuppressed()&&!c.IsFixed()&&c.GetPathName().EndsWith(".SLDPRT",StringComparison.OrdinalIgnoreCase))){string componentReference=Convert.ToBase64String((byte[])s.Doc.Extension.GetPersistReference3(c)),componentId=StableId("component_",componentReference);int count=0;foreach(var f in Faces(c).OrderByDescending(f=>f.GetArea())){var surface=(ISurface)f.GetSurface();if(!surface.IsCylinder()&&!surface.IsPlane())continue;if(++count>64)break;string reference=Convert.ToBase64String((byte[])s.Doc.Extension.GetPersistReference3(f)),entity=StableId("entity_",reference);m.Entities[entity]=reference;double[] v=surface.IsCylinder()?((double[])surface.CylinderParams).Skip(3).Take(3).ToArray():((double[])surface.PlaneParams).Take(3).ToArray();double[] axis=ApplyPose((double[])c.GetTotalTransform(false).ArrayData,v,false);double norm=Math.Sqrt(axis.Sum(x=>x*x));axis=axis.Select(x=>x/norm).ToArray();entities.Add(new{entity_id=entity,component_id=componentId,instance=c.Name2,kind=surface.IsCylinder()?"cylindrical_axis":"planar_normal",suggested_motor=surface.IsCylinder()?"rotary":"linear",axis_global=axis,area_m2=f.GetArea(),requires_user_selection=true});}}SaveUserModel(m);return new{model_id=id,components=components,entities=entities,claim="geometric_candidates_only_no_automatic_design_intent_inference"};}}
    public object CreateUserStudy(string id,string studyName,string componentId,string entityId,string kind,double speed,bool reverse){
        var m=GetUserModel(id);if(Sw.RevisionNumber()!="34.0.0")throw new Exception("MOTOR_ADAPTER_UNCALIBRATED_VERSION");if(string.IsNullOrWhiteSpace(studyName)||studyName.Length>80||(kind!="rotary"&&kind!="linear")||double.IsNaN(speed)||double.IsInfinity(speed)||speed<=0||speed>(kind=="rotary"?6000:500))throw new Exception("INVALID_DRIVE_OPTIONS");
        var checkpoint=Json.Deserialize<Dictionary<string,object>>(Json.Serialize(CreateUserCheckpoint(id)));string cp=(string)checkpoint["checkpoint_id"];LoadUserMotion();LastOperationRestoration="pending";
        try{using(var s=new Scope(this,m.Path,null)){RequireUserReady(m,s.Doc,null);var mgr=(IMotionStudyManager)s.Doc.Extension.GetMotionStudyManager();if(Names(mgr).Contains(studyName))throw new Exception("STUDY_ALREADY_EXISTS");foreach(string n in Names(mgr)){var old=(IMotionStudy)mgr.GetMotionStudy(n);if(old.IsActive&&Math.Abs(old.GetTime())>1e-8)throw new Exception("CREATE_STUDY_REQUIRES_INITIAL_TIME");}
            var c=ResolveUserComponent(m,s.Doc,componentId);if(c.IsFixed())throw new Exception("DRIVE_COMPONENT_FIXED");string reference;if(!m.Entities.TryGetValue(entityId,out reference))throw new Exception("DRIVE_ENTITY_NOT_FOUND");int error;var face=s.Doc.Extension.GetObjectByPersistReference3(Convert.FromBase64String(reference),out error) as IFace2;if(face==null||error!=0)throw new Exception("DRIVE_ENTITY_STALE");var owner=((IEntity)face).GetComponent() as IComponent2;if(owner==null||owner.Name2!=c.Name2)throw new Exception("DRIVE_ENTITY_COMPONENT_MISMATCH");var surf=(ISurface)face.GetSurface();if(kind=="rotary"&&!surf.IsCylinder()||kind=="linear"&&!surf.IsPlane())throw new Exception("DRIVE_ENTITY_TYPE_MISMATCH");
            double[] axis=ApplyPose((double[])c.GetTotalTransform(false).ArrayData,kind=="rotary"?((double[])surf.CylinderParams).Skip(3).Take(3).ToArray():((double[])surf.PlaneParams).Take(3).ToArray(),false);double norm=Math.Sqrt(axis.Sum(x=>x*x));axis=axis.Select(x=>x/norm).ToArray();
            var study=(IMotionStudy)mgr.CreateMotionStudy();study.Name=studyName;study.Activate();study.StudyType=4;if(study.StudyType!=4)throw new Exception("MOTION_LICENSE_UNAVAILABLE");var motor=(ISimulationMotorFeatureData)study.CreateDefinition(kind=="rotary"?78:77);motor.DirectionReference=face;motor.Location=face;motor.ReverseDirection=reverse;motor.ConstantSpeedMotor(kind=="rotary"?speed*2*Math.PI/60:speed/1000);if(study.CreateFeature(motor)==null)throw new Exception("MOTOR_CREATE_FAILED");study.SetDuration(1);((IMotionStudyProperties)study.GetProperties(4)).SetFrameRate(30);
            m.Drives[studyName]=new UserDrive{Study=studyName,ComponentId=componentId,EntityId=entityId,Kind=kind,Speed=speed,Reverse=reverse,Axis=axis};Save(s.Doc,m.Path);m.Revision++;SaveUserModel(m);LastOperationRestoration="restored";return new{model_id=id,study=studyName,motor_type=kind,speed=speed,speed_unit=kind=="rotary"?"rpm":"mm/s",reverse_direction=reverse,axis_global=axis,checkpoint_id=cp,results_invalidated=true,requires_solver_drive_validation=true,restoration_status="restored"};}
        }catch{try{RestoreUserCheckpoint(id,cp);}catch{LastOperationRestoration="unknown";throw new Exception("STUDY_CREATION_ROLLBACK_FAILED");}throw;}
    }
    public object ConvertUserStudy(string id,string studyName){var m=GetUserModel(id);var cp=Json.Deserialize<Dictionary<string,object>>(Json.Serialize(CreateUserCheckpoint(id)));LoadUserMotion();try{using(var s=new Scope(this,m.Path,null)){var study=(IMotionStudy)((IMotionStudyManager)s.Doc.Extension.GetMotionStudyManager()).GetMotionStudy(studyName);if(study==null)throw new Exception("STUDY_NOT_FOUND");int previous=study.StudyType;study.StudyType=4;if(study.StudyType!=4)throw new Exception("MOTION_LICENSE_UNAVAILABLE");Save(s.Doc,m.Path);m.Revision++;SaveUserModel(m);return new{model_id=id,study=studyName,previous_type=previous,current_type=4,checkpoint_id=cp["checkpoint_id"],results_invalidated=true};}}catch{RestoreUserCheckpoint(id,(string)cp["checkpoint_id"]);throw;}}
    static double[] RotationIncrement(double[] before,double[] after){var q=new double[9];for(int i=0;i<3;i++)for(int j=0;j<3;j++)q[3*i+j]=Enumerable.Range(0,3).Sum(k=>before[3*k+i]*after[3*k+j]);double angle=Math.Acos(Math.Max(-1,Math.Min(1,(q[0]+q[4]+q[8]-1)/2)));if(angle>Math.PI-.001)throw new Exception("ROTATION_SAMPLE_AMBIGUOUS");double factor=angle<1e-7?.5:angle/(2*Math.Sin(angle));return new[]{(q[5]-q[7])*factor,(q[6]-q[2])*factor,(q[1]-q[3])*factor};}
    double[] NativeUserTimes(IMotionStudy study,IModelDoc2 doc){var c=UserComponents(doc).First(v=>!v.IsSuppressed()&&!v.IsFixed()&&v.GetPathName().EndsWith(".SLDPRT",StringComparison.OrdinalIgnoreCase));var results=(ICosmosMotionStudyResults)study.GetResults(4);var plot=(IMotionPlotFeatureData)results.CreatePlotFeatureData();var x=(IMotionPlotAxisFeatureData)results.CreatePlotXAxisFeatureData();x.Type=0;var y=(IMotionPlotAxisFeatureData)results.CreatePlotYAxisFeatureData();y.Type=7;y.Component=0;y.Entities=new[]{new DispatchWrapper(Faces(c).First())};var output=results.GetValues(plot,x,new[]{new DispatchWrapper(y)}) as IMotionPlotFeatureOutput;if(output==null)throw new Exception("NATIVE_TIME_AXIS_UNAVAILABLE");return (double[])output.GetXAxis();}
    public object RunUserStudy(string id,string studyName,double duration,int fps,string runId){
        if(Sw.RevisionNumber()!="34.0.0")throw new Exception("MOTION_ADAPTER_UNCALIBRATED_VERSION");var m=GetUserModel(id);if(double.IsNaN(duration)||double.IsInfinity(duration)||duration<=0||duration>30||fps<5||fps>120||Math.Abs(duration*fps-Math.Round(duration*fps))>1e-8||(int)Math.Round(duration*fps)+1>1801)throw new Exception("MOTION_BUDGET_REJECTED");LoadUserMotion();var scope=new Scope(this,m.Path,studyName);Run run=null;object driveAudit=null;
        try{RequireUserReady(m,scope.Doc,studyName);int n=(int)Math.Round(duration*fps)+1;var current=Transforms(scope.Doc);if(current.Count*n>100000)throw new Exception("POSE_SAMPLE_BUDGET_EXCEEDED");UserDrive drive;m.Drives.TryGetValue(studyName,out drive);if(drive!=null&&drive.Kind=="rotary"&&drive.Speed/fps>7.5)throw new Exception("OUTPUT_FPS_TOO_LOW_FOR_REQUESTED_ROTATION");
            scope.Study.SetDuration(duration);((IMotionStudyProperties)scope.Study.GetProperties(4)).SetFrameRate(fps);if(scope.Study.StudyType!=4||((IMotionStudyProperties)scope.Study.GetProperties(4)).GetFrameRate()!=fps)throw new Exception("SOLVER_SETTINGS_UNVERIFIED");if(!scope.Doc.EditRebuild3())throw new Exception("REBUILD_FAILED");Progress(activeJobId,"native_calculate",0,n,runId);if(!scope.Study.Calculate())throw new Exception("SOLVER_FAILED");var native=(IMotionStudyResults)scope.Study.GetResults(4);if(native==null||native.IsOutOfDate())throw new Exception("RESULTS_STALE");var times=NativeUserTimes(scope.Study,scope.Doc);if(times.Length!=n||times.Where((v,i)=>double.IsNaN(v)||Math.Abs(v-(double)i/fps)>1e-7).Any())throw new Exception("NATIVE_TIME_AXIS_MISMATCH");var poses=current.Keys.ToDictionary(k=>k,k=>new double[n][]);
            for(int i=0;i<n;i++){scope.EnsureActive();scope.Study.SetTime(Argument(times[i],duration));Application.DoEvents();var p=Transforms(scope.Doc);if(!p.Keys.OrderBy(x=>x).SequenceEqual(poses.Keys.OrderBy(x=>x)))throw new Exception("COMPONENT_SCOPE_CHANGED");foreach(var v in p){if(v.Value.Any(x=>double.IsNaN(x)||double.IsInfinity(x)))throw new Exception("NONFINITE_SOLVER_POSE");poses[v.Key][i]=v.Value;}Progress(activeJobId,"capture_solver_poses",i+1,n,runId);}
            if(native.IsOutOfDate())throw new Exception("RESULTS_STALE");if(drive!=null){var component=ResolveUserComponent(m,scope.Doc,drive.ComponentId);var p=poses[component.Name2];double observed=drive.Kind=="rotary"?Enumerable.Range(1,n-1).Sum(i=>RotationIncrement(p[i-1],p[i]).Zip(drive.Axis,(a,b)=>a*b).Sum())/duration*30/Math.PI:p[n-1].Skip(9).Take(3).Zip(p[0].Skip(9).Take(3),(a,b)=>a-b).Zip(drive.Axis,(a,b)=>a*b).Sum()/duration*1000;double error=Math.Abs(Math.Abs(observed)-drive.Speed);driveAudit=new{kind=drive.Kind,requested=drive.Speed,observed_signed=observed,unit=drive.Kind=="rotary"?"rpm":"mm/s",absolute_magnitude_error=error,expected_direction="SolidWorks motor arrow and reverse flag",validation="independent_solver_pose_displacement_or_rotation"};if(error>Math.Max(.001,drive.Speed*.005))throw new Exception("DRIVE_VALIDATION_FAILED "+Json.Serialize(driveAudit));}
            string dir=Path.Combine(Root,"runs",runId);Directory.CreateDirectory(dir);var names=new Dictionary<string,string>();foreach(var kv in m.Components){try{var c=ResolveUserComponent(m,scope.Doc,kv.Key);if(poses.ContainsKey(c.Name2))names[kv.Key]=c.Name2;}catch(Exception e){if(!e.Message.StartsWith("COMPONENT_REFERENCE_STALE"))throw;}}
            run=new Run{Id=runId,Assembly=id,Generic=true,ModelRoot=m.Directory,EditVersion=m.Revision,Path=m.Path,Study=studyName,Fingerprint=Fingerprint(scope.Doc),Duration=duration,Fps=fps,Directory=dir,Times=times,Poses=poses,ComponentNames=names};
            using(var csv=new StreamWriter(Path.Combine(dir,"component-poses.csv"))){csv.WriteLine("frame,time_s,component_id,instance,x_m,y_m,z_m,r00,r01,r02,r10,r11,r12,r20,r21,r22");for(int i=0;i<n;i++)foreach(var c in names){var p=poses[c.Value][i];csv.WriteLine(i+","+times[i].ToString("R",CultureInfo.InvariantCulture)+",\""+c.Key+"\",\""+c.Value.Replace("\"","\"\"")+"\","+string.Join(",",p.Skip(9).Take(3).Concat(p.Take(9)).Select(v=>v.ToString("R",CultureInfo.InvariantCulture))));}}
        }finally{scope.Dispose();}if(!scope.Restored)throw new Exception("RESTORATION_FAILED");runs[runId]=run;var summary=new{run_id=runId,model_id=id,study=studyName,solver="Motion Analysis",solver_status="completed",solidworks_process_id=Sw.GetProcessID(),solidworks_revision=Sw.RevisionNumber(),duration_s=duration,output_fps=fps,frames=run.Times.Length,components=run.Poses.Count,model_revision=m.Revision,native_time_axis_verified=true,drive_validation=driveAudit,validation_scope=driveAudit==null?"native_calculate_fresh_results_time_axis_and_restoration; no independent physics oracle":"native_results_and_independent_requested_drive_magnitude",degrees_of_freedom_status="unknown",restoration_status="restored",maximum_restore_transform_delta=scope.RestoreDelta,poses_csv=Path.Combine(run.Directory,"component-poses.csv"),source_files_unchanged=UserSourcesUnchanged(m)};AtomicJson(Path.Combine(run.Directory,"solve.json"),summary);return summary;
    }
    public object UserRunSummary(string id){var r=GetRun(id);if(!r.Generic)throw new Exception("USER_MOTION_RUN_REQUIRED");using(var s=new Scope(this,r.Path,r.Study)){ValidateRun(r,s);return Json.DeserializeObject(File.ReadAllText(Path.Combine(r.Directory,"solve.json")));}}
    public object ExportUserCurve(string id,string componentId,string quantity,string axis){var r=GetRun(id);if(!r.Generic||!r.ComponentNames.ContainsKey(componentId))throw new Exception("RUN_COMPONENT_NOT_FOUND");if(!new[]{"position","displacement","linear_velocity","angular_velocity"}.Contains(quantity)||!new[]{"x","y","z","magnitude"}.Contains(axis))throw new Exception("CURVE_OPTIONS_UNSUPPORTED");using(var s=new Scope(this,r.Path,r.Study)){ValidateRun(r,s);var p=r.Poses[r.ComponentNames[componentId]];var vectors=new double[p.Length][];string unit=quantity=="linear_velocity"?"m/s":quantity=="angular_velocity"?"rad/s":"m";
            for(int i=0;i<p.Length;i++){if(quantity=="position")vectors[i]=p[i].Skip(9).Take(3).ToArray();else if(quantity=="displacement")vectors[i]=p[i].Skip(9).Take(3).Zip(p[0].Skip(9).Take(3),(a,b)=>a-b).ToArray();else{int a=i==0?0:i-1,b=i==p.Length-1?i:i+1;double dt=r.Times[b]-r.Times[a];vectors[i]=quantity=="angular_velocity"?RotationIncrement(p[a],p[b]).Select(x=>x/dt).ToArray():p[b].Skip(9).Take(3).Zip(p[a].Skip(9).Take(3),(x,y)=>(x-y)/dt).ToArray();}}
            int k=axis=="x"?0:axis=="y"?1:2;var values=vectors.Select(v=>axis=="magnitude"?Math.Sqrt(v.Sum(x=>x*x)):v[k]).ToArray();string path=Path.Combine(r.Directory,componentId+"_"+quantity+"_"+axis+".csv");using(var csv=new StreamWriter(path)){csv.WriteLine("time_s,value_"+unit.Replace("/","_per_"));for(int i=0;i<values.Length;i++)csv.WriteLine(r.Times[i].ToString("R",CultureInfo.InvariantCulture)+","+values[i].ToString("R",CultureInfo.InvariantCulture));}return new{run_id=id,component_id=componentId,instance=r.ComponentNames[componentId],quantity=quantity,axis=axis,unit=unit,coordinate_frame="assembly_global",reference_point="component_coordinate_origin_not_center_of_mass",source=quantity.Contains("velocity")?"numeric_derivative_of_solver_poses":"solver_component_origin_pose",derivative_scheme="central_difference_interior_one_sided_endpoints",sample_count=values.Length,min=values.Min(),max=values.Max(),csv_path=path,warning="sampled pose derivatives; not a native instantaneous velocity plot; rotation aliasing possible for unvalidated existing drives"};}}
    public object ReplayUserFrame(string id,int frame){var r=GetRun(id);if(!r.Generic||frame<0||frame>=r.Times.Length)throw new Exception("FRAME_OUTSIDE_RUN");var s=new Scope(this,r.Path,r.Study);string image=null;double delta=0;try{ValidateRun(r,s);s.Study.SetTime(Argument(r.Times[frame],r.Duration));Application.DoEvents();delta=Transforms(s.Doc).Max(p=>p.Value.Zip(r.Poses[p.Key][frame],(a,b)=>Math.Abs(a-b)).Max());if(delta>1e-7)throw new Exception("POSE_MISMATCH");image=Path.Combine(r.Directory,"motion-frame-"+frame+".bmp");s.Doc.GraphicsRedraw2();if(!s.Doc.SaveBMP(image,1200,900))throw new Exception("FRAME_IMAGE_EXPORT_FAILED");}finally{s.Dispose();}return new{run_id=id,frame=frame,time_s=r.Times[frame],image_path=image,maximum_pose_difference=delta,restoration_status="restored"};}
    public object CreateUserCheckpoint(string id){LoadUserMotion();var m=GetUserModel(id);using(var s=new Scope(this,m.Path,null)){Fingerprint(s.Doc);var mgr=(IMotionStudyManager)s.Doc.Extension.GetMotionStudyManager();var states=Names(mgr).Select(n=>{var study=(IMotionStudy)mgr.GetMotionStudy(n);return new{name=n,type=study.StudyType,time_s=study.GetTime(),duration_s=study.GetDuration(),fps=((IMotionStudyProperties)study.GetProperties(study.StudyType)).GetFrameRate(),active=study.IsActive};}).ToArray();if(states.Any(v=>v.active&&Math.Abs(v.time_s)>1e-8))throw new Exception("CHECKPOINT_REQUIRES_INITIAL_TIME");Save(s.Doc,m.Path);string cp=Guid.NewGuid().ToString("N"),dir=Path.Combine(m.Directory,"checkpoints",cp);Directory.CreateDirectory(dir);var files=new Dictionary<string,string>();foreach(string path in m.Files){string copy=Path.Combine(dir,Path.GetFileName(path));File.Copy(path,copy,false);files[path]=FileHash(copy);}var descriptor=new{checkpoint_id=cp,model_id=id,files=files,configuration=s.Doc.ConfigurationManager.ActiveConfiguration.Name,poses=Transforms(s.Doc),studies=states,model=m};AtomicJson(Path.Combine(dir,"checkpoint.json"),descriptor);return new{model_id=id,checkpoint_id=cp,file_count=files.Count,checkpoint_path=Path.Combine(dir,"checkpoint.json")};}}
    void CloseUserDocuments(string[] paths){var documents=(Sw.GetDocuments() as object[]??new object[0]).Cast<IModelDoc2>().Select(doc=>new{path=doc.GetPathName(),title=doc.GetTitle(),type=doc.GetType()}).Where(doc=>paths.Contains(doc.path,StringComparer.OrdinalIgnoreCase)).OrderByDescending(doc=>doc.type).ToArray();foreach(var item in documents)if((Sw.GetDocuments() as object[]??new object[0]).Cast<IModelDoc2>().Any(doc=>doc.GetPathName().Equals(item.path,StringComparison.OrdinalIgnoreCase)))Sw.CloseDoc(item.title);}
    public object RestoreUserCheckpoint(string id,string cp){var m=GetUserModel(id);if(!Regex.IsMatch(cp??"","^[a-f0-9]{32}$"))throw new Exception("INVALID_CHECKPOINT_ID");string dir=Path.Combine(m.Directory,"checkpoints",cp),path=Path.Combine(dir,"checkpoint.json");if(!File.Exists(path))throw new Exception("CHECKPOINT_NOT_FOUND");var d=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(path));if((string)d["model_id"]!=id)throw new Exception("CHECKPOINT_MODEL_MISMATCH");var files=(Dictionary<string,object>)d["files"];if(files.Count!=m.Files.Length||m.Files.Any(p=>!files.ContainsKey(p)))throw new Exception("CHECKPOINT_FILE_SET_CHANGED");foreach(var f in files){OwnedPath(f.Key,"user_assemblies");string snapshot=OwnedPath(Path.Combine(dir,Path.GetFileName(f.Key)),"user_assemblies");if(FileHash(snapshot)!=(string)f.Value)throw new Exception("CHECKPOINT_INTEGRITY_FAILED");}LastOperationRestoration="pending";
        CloseUserDocuments(m.Files);if((Sw.GetDocuments() as object[]??new object[0]).Cast<IModelDoc2>().Any(doc=>m.Files.Contains(doc.GetPathName(),StringComparer.OrdinalIgnoreCase)))throw new Exception("CHECKPOINT_DOCUMENT_STILL_OPEN");foreach(var f in files)File.Copy(Path.Combine(dir,Path.GetFileName(f.Key)),f.Key,true);
        var restored=Json.Deserialize<UserModel>(Json.Serialize(d["model"]));restored.Revision=Math.Max(m.Revision,restored.Revision)+1;SaveUserModel(restored);LoadUserMotion();using(var s=new Scope(this,restored.Path,null)){if(s.Doc.ConfigurationManager.ActiveConfiguration.Name!=(string)d["configuration"]&&!s.Doc.ShowConfiguration2((string)d["configuration"]))throw new Exception("CHECKPOINT_CONFIGURATION_MISMATCH");var mgr=(IMotionStudyManager)s.Doc.Extension.GetMotionStudyManager();foreach(Dictionary<string,object> state in (System.Collections.IEnumerable)d["studies"]){var study=(IMotionStudy)mgr.GetMotionStudy((string)state["name"]);if(study==null)throw new Exception("CHECKPOINT_STUDY_MISSING");study.StudyType=Convert.ToInt32(state["type"]);study.SetDuration(Convert.ToDouble(state["duration_s"]));((IMotionStudyProperties)study.GetProperties(study.StudyType)).SetFrameRate(Convert.ToInt32(state["fps"]));if((bool)state["active"]){study.Activate();study.SetTime(Convert.ToDouble(state["time_s"]));Application.DoEvents();}}
            foreach(Dictionary<string,object> state in (System.Collections.IEnumerable)d["studies"]){var check=(IMotionStudy)mgr.GetMotionStudy((string)state["name"]);if(check.StudyType!=Convert.ToInt32(state["type"])||Math.Abs(check.GetDuration()-Convert.ToDouble(state["duration_s"]))>1e-8||((IMotionStudyProperties)check.GetProperties(check.StudyType)).GetFrameRate()!=Convert.ToInt32(state["fps"]))throw new Exception("CHECKPOINT_SETTINGS_MISMATCH");}if(s.Doc.ConfigurationManager.ActiveConfiguration.Name!=(string)d["configuration"])throw new Exception("CHECKPOINT_CONFIGURATION_MISMATCH");var actual=Transforms(s.Doc);var expected=(Dictionary<string,object>)d["poses"];if(actual.Count!=expected.Count)throw new Exception("CHECKPOINT_COMPONENT_SET_MISMATCH");double delta=expected.Max(v=>((System.Collections.IEnumerable)v.Value).Cast<object>().Select(Convert.ToDouble).Zip(actual[v.Key],(a,b)=>Math.Abs(a-b)).Max());if(delta>1e-7||files.Any(f=>FileHash(f.Key)!=(string)f.Value))throw new Exception("CHECKPOINT_RESTORE_UNVERIFIED");Fingerprint(s.Doc);bool sourcesUnchanged=UserSourcesUnchanged(restored);LastOperationRestoration="restored";return new{model_id=id,checkpoint_id=cp,restoration_status="restored",maximum_transform_delta=delta,results_invalidated=true,model_revision=restored.Revision,source_files_unchanged=sourcesUnchanged,simulation_input="checkpoint_imported_copy"};}
    }
